from flask import Flask, request, jsonify, redirect
import redis
import pymongo
import string

app = Flask(__name__)

# Database and Cache connections
mongo_client = pymongo.MongoClient("mongodb://localhost:27017/")
db = mongo_client["url_shortener"]
urls_collection = db["urls"]
redis_client = redis.Redis(host='localhost', port=6379, db=0, decode_responses=True)

BASE62_CHARS = string.digits + string.ascii_letters

def encode_base62(num):
    if num == 0:
        return BASE62_CHARS[0]
    res = []
    while num > 0:
        num, rem = divmod(num, 62)
        res.append(BASE62_CHARS[rem])
    return ''.join(reversed(res))

# Simulated ZooKeeper local counter
local_counter = 1000000

@app.route('/shorten', methods=['POST'])
def shorten_url():
    global local_counter
    data = request.get_json() or {}
    long_url = data.get('url')
    custom_alias = data.get('custom_alias')

    if not long_url:
        return jsonify({'error': 'URL is required'}), 400

    if custom_alias:
        if urls_collection.find_one({'_id': custom_alias}):
            return jsonify({'error': 'Custom alias already taken'}), 409
        short_code = custom_alias
    else:
        local_counter += 1
        short_code = encode_base62(local_counter)

    urls_collection.insert_one({'_id': short_code, 'long_url': long_url})
    redis_client.set(short_code, long_url, ex=86400) # Cache for 24h

    return jsonify({'short_url': request.host_url + short_code}), 201

@app.route('/<string:short_code>', methods=['GET'])
def resolve_url(short_code):
    # 1. Cache hit check
    cached_url = redis_client.get(short_code)
    if cached_url:
        return redirect(cached_url, code=302)

    # 2. Database lookup
    record = urls_collection.find_one({'_id': short_code})
    if record:
        original_url = record['long_url']
        redis_client.set(short_code, original_url, ex=86400)
        return redirect(original_url, code=302)

    return jsonify({'error': 'Short URL not found'}), 404

if __name__ == '__main__':
    app.run(port=5000, debug=True)

