import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.Map;

public class URLShortenerService {
    private static final String BASE62 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private final Map<String, String> shortToLongMap = new ConcurrentHashMap<>();
    private final Map<String, String> longToShortMap = new ConcurrentHashMap<>();
    private final AtomicLong counter = new AtomicLong(10000000L);

    public String shortenURL(String originalURL) {
        if (longToShortMap.containsKey(originalURL)) {
            return longToShortMap.get(originalURL);
        }
        long id = counter.incrementAndGet();
        String shortCode = encodeBase62(id);
        shortToLongMap.put(shortCode, originalURL);
        longToShortMap.put(originalURL, shortCode);
        return "https://tiny.url/" + shortCode;
    }

    public String getOriginalURL(String shortCode) {
        return shortToLongMap.get(shortCode);
    }

    private String encodeBase62(long num) {
        StringBuilder sb = new StringBuilder();
        while (num > 0) {
            sb.append(BASE62.charAt((int) (num % 62)));
            num /= 62;
        }
        return sb.reverse().toString();
    }
}
